<template>
  <div class="mobile-chat-main" :style="chatMainStyle">
    <!-- 移动端导航栏 -->
    <mobile-app-navbar :isShowLogo="false" :isShowHistoryButton2="false" />
    
    <!-- 移动端消息区域 -->
    <mobile-message-list
      ref="messageListRef"
      :sessionId="sessionId"
      :paddingTop="'0'"
      @onFinishTyping="onFinish"
      @onLoadComplete="onMessagesLoaded"
      @onRetryMessage="onRetryMessage"
    />
    
    <!-- 输入框 -->
    <div ref="inputContainerRef" class="mobile-input">
      <mobile-input-ai-chat
        ref="refInput"
        width="100%"
        @onSend="onSendMsg"
        @onSendStop="onSendStop"
        :isSend="isSend"
        :initialModel="aiChatStore.getAIChatParams()?.model"
        :initialThinking="aiChatStore.getAIChatParams()?.isThinking"
        :initialEnableSearch="aiChatStore.getAIChatParams()?.enable_search"
      />
    </div>
  </div>
</template>

<script setup>
// 引入区域
import { ref, onMounted, onUnmounted, computed, nextTick, onBeforeUnmount, watch, onBeforeMount } from 'vue';
import { useUserStore } from '@/store/modules/user';
import { useAIChatStore } from '@/store/modules/AIChat';
import { useConversationStore } from '@/store/modules/conversation';
import { MSG_ROLE_USER, MSG_ROLE_ASSISTANT, MESSAGE_STATUS, onSendParseMsg, onAIParseMsg } from '@/types/msg.ts';
import { useRoute, useRouter } from 'vue-router';
import { ROUTER_PATHS } from '@/router/constants';
import { ApiChat } from '@/api/api-chat';
import { showMessageError } from '@/utils/mobile-ui-feedback';
import MobileMessageList from '@/mobile/components/business/mobile-message-list.vue';
import MobileAppNavbar from '@/mobile/components/layout/mobile-app-navbar.vue';
import MobileInputAiChat from '@/mobile/components/business/mobile-input-ai-chat.vue';
import { pxToRem } from '@/utils/px-to-rem';

// 变量区域
const aiChatStore = useAIChatStore();
const conversationStore = useConversationStore();
const userStore = useUserStore();
const route = useRoute();
const router = useRouter();

const isSend = ref(false);
const refInput = ref();
const inputContainerRef = ref();
const messageListRef = ref();
const msgId = ref();
const isStreamDone = ref(false);
const sessionId = ref(0);
const bottomHeight = ref(0);
const windowWidth = ref(window.innerWidth);
const streamConnection = ref(null);

// 计算属性区域
const chatMainStyle = computed(() => {
  return {
    display: 'flex',
    flexDirection: 'column'
  };
});

// 自定义事件区域
const onMessagesLoaded = (status) => {
  if(status){
    // 消息加载完成的处理逻辑
  }
};

const onFinish = () => {
  setTimeout(() => {
    if (!isStreamDone.value) return
    isSend.value = false;
    msgId.value = null;
    refInput.value.isLoading = false;
    isStreamDone.value = false;
  }, 300);
};

// 重试消息处理（使用当前最新设置）
// 🔧 重要改进：重试时使用当前用户选择的最新设置（模型、思考模式、搜索设置）
// 而不是发送失败时保存的旧设置，这样用户可以在重试前调整设置
const onRetryMessage = async (messageId) => {
  const msgList = messageListRef.value.msgList;
  const message = msgList.find(msg => msg.id === messageId);

  if (!message || !message.originalContent) {
    console.warn('Cannot retry message: message not found or missing original content');
    return;
  }

  // 获取当前最新的设置参数（用户可能已经修改了模型、思考模式或搜索设置）
  const currentParams = aiChatStore.getAIChatParams() || {};
  
  // 构建重试参数：使用原始内容 + 当前最新设置
  const retryParams = {
    content: message.originalContent, // 保持原始消息内容不变
    model: currentParams.model || message.originalModel || 'default-model', // 优先使用当前选择的模型
    isThinking: currentParams.isThinking !== undefined ? currentParams.isThinking : (message.originalIsThinking || false), // 使用当前思考模式设置
    enable_search: currentParams.enable_search !== undefined ? currentParams.enable_search : (message.originalEnableSearch || false) // 使用当前搜索设置
  };

  console.log('重试消息 - 使用最新参数:', retryParams);

  // 重置消息状态
  message.messageStatus = MESSAGE_STATUS.SENDING;
  message.showLoading = true;
  message.isRetrying = true;
  message.content = '';

  // 根据当前设置重置相关状态
  if (retryParams.isThinking) {
    message.hasThinking = true;
    message.reasoning_content = '';
    message.thinking_status = 'start';
  } else {
    message.hasThinking = false;
    message.reasoning_content = '';
    message.thinking_status = 'end';
  }

  // 重置DeepSearch相关状态
  if (retryParams.enable_search) {
    message.hasDeepSearch = true;
    message.isSearching = true;
    message.search_citations = null;
    message.deepSearchStreamData = null;
  } else {
    message.hasDeepSearch = false;
    message.isSearching = false;
    message.search_citations = null;
    message.deepSearchStreamData = null;
  }

  try {
    // 根据当前的思考模式设置选择发送方法
    if (retryParams.isThinking) {
      await sendNormalMessage(retryParams, messageId);
    } else {
      await sendStreamMessage(retryParams, messageId);
    }

    // 成功后更新状态
    message.messageStatus = MESSAGE_STATUS.SUCCESS;
    message.isRetrying = false;

  } catch (error) {
    console.error('Retry failed:', error);
    // 重试失败，重新标记为失败状态
    message.messageStatus = MESSAGE_STATUS.FAILED;
    message.showLoading = false;
    message.isRetrying = false;
  }
};

// 业务逻辑区域
const handleResize = () => {
  windowWidth.value = window.innerWidth;
};

const getBottomHeight = () => {
  nextTick(() => {
    bottomHeight.value = inputContainerRef.value.offsetHeight;
  });
};

const cleanupEventListeners = () => {
  window.removeEventListener('resize', handleResize);
};

const cancelStreamMessage = () => {
  if (streamConnection.value) {
    streamConnection.value.close();
    streamConnection.value = null;
    return true;
  }
  return false;
};

/**
 * 使用流式消息发送
 * @param {object} data - 消息数据，包含content、model、enable_search等信息
 * @param {number|null} id - 本地消息ID
 */
const sendStreamMessage = (data, id) => {
  // 先关闭之前的连接（如果存在）
  if (streamConnection.value) {
    streamConnection.value.close();
    streamConnection.value = null;
  }

  // 用于累积完整的响应
  let fullResponse = '';

  // 构建发送参数
  const sendParams = {
    session_id: sessionId.value || null,
    content: data.content || data,
    streaming: true,
    model: data.model,
    enable_search: data.enable_search ?? false
  };

  // 使用流式消息API并保存连接对象
  streamConnection.value = ApiChat.sendStreamChatMessage(
    sendParams,
    (streamData) => {
      isStreamDone.value = false;
      // 处理流式消息片段
      const msgList = messageListRef.value.msgList;
      let item = msgList.find(item => item.id === id);
      if (item) {
        item.showLoading = false;
        item.isMarkdown = true;

        // 处理 citations 数据
        if (streamData.citations && Array.isArray(streamData.citations)) {
          item.search_citations = streamData.citations;
          return;
        }

        // 获取内容
        const content = streamData.content || '';
        fullResponse += content;

        // 追加内容而不是替换
        if (item.content === undefined || item.content === null) {
          item.content = '';
        }
        item.content += content;

        // 如果启用了DeepSearch，设置相关属性
        if (data.enable_search) {
          item.hasDeepSearch = true;
          item.isSearching = streamData.is_searching !== false;

          // 传递流式数据给DeepSearch组件
          if (item.deepSearchStreamData !== streamData) {
            item.deepSearchStreamData = { ...streamData };
          }
        }
      }
    },
    (error) => {
      // 处理错误 - 标记消息为失败状态
      const msgList = messageListRef.value.msgList;
      let item = msgList.find(item => item.id === id);
      if (item) {
        item.messageStatus = MESSAGE_STATUS.FAILED;
        item.showLoading = false;
        item.isRetrying = false;

        // 只保存原始消息内容用于重试，其他参数使用当前最新设置
        if (!item.originalContent) {
          item.originalContent = data.content || '';
        }
      }

      // 清除连接引用
      streamConnection.value = null;
      isSend.value = false;
      msgId.value = null;
      if (refInput.value) {
        refInput.value.isLoading = false;
      }
      isStreamDone.value = true;
    },
    (finalData) => {
      isStreamDone.value = true;
      // 流结束时，更新 store 中的AI助手消息
      const msgList = messageListRef.value.msgList;
      let item = msgList.find(item => item.id === id);
      if (item && sessionId.value) {
        // 如果是DeepSearch，标记搜索完成
        if (data.enable_search && item.hasDeepSearch) {
          item.isSearching = false;

          // 处理搜索引用链接（如果有）
          if (finalData.search_citations && Array.isArray(finalData.search_citations)) {
            item.search_citations = finalData.search_citations;
            console.log('Mobile DeepSearch completed with citations:', finalData.search_citations);
          }
        }

        // 使用updateMessageInConversation方法更新现有消息
        conversationStore.updateMessageInConversation(sessionId.value, item.id, {
          content: fullResponse,
          role: MSG_ROLE_ASSISTANT,
          isMarkdown: true,
          hasDeepSearch: item.hasDeepSearch,
          search_citations: item.search_citations || []
        });
      }

      // 清除连接引用
      streamConnection.value = null;
    }
  );
};

/**
 * 使用非流式消息发送
 * @param {object} data - 消息数据，包含content、model、isThinking、enable_search等信息
 * @param {number|null} id - 本地消息ID
 */
const sendNormalMessage = (data, id) => {
  // 构建发送参数
  const sendParams = {
    session_id: sessionId.value,
    content: data.content || data,
    model: data.model,
    reasoning: data.isThinking || false,
    enable_search: data.enable_search ?? false
  };

  ApiChat.sendChatMessage(sendParams).then(res => {
    const msgList = messageListRef.value.msgList;
    let item = msgList.find(item => item.id === id);
    if (!item) {
      console.warn('Cannot find message item with id:', id);
      return;
    }

    // 保存原始ID用于store更新
    const originalId = item.id;

    item.isMarkdown = true;
    item.showLoading = false;
    item.content = res?.data?.content || '';

    // 处理Think模式的推理内容
    if (res?.data?.reasoning_content && data.isThinking) {
      item.reasoning_content = res.data.reasoning_content;
      item.hasThinking = true;
      item.thinking_status = 'end';
    }

    // 处理DeepSearch的搜索引用链接
    if (res?.data?.search_citations && data.enable_search) {
      item.search_citations = res.data.search_citations;
      item.hasDeepSearch = true;
      item.isSearching = false;
    }

    // 更新消息ID为服务器返回的ID
    item.id = res?.data?.id;
    msgId.value = res?.data?.id;

    if (!sessionId.value) {
      sessionId.value = res?.data?.session_id;
      // 使用路径参数方式
      router.replace({
        path: `${ROUTER_PATHS.ALIEN_CHAT}/${sessionId.value}`
      });
    }

    // 更新conversationStore中的消息
    if (sessionId.value) {
      conversationStore.updateMessageInConversation(sessionId.value, originalId, {
        id: item.id,
        content: item.content,
        role: MSG_ROLE_ASSISTANT,
        isMarkdown: true,
        reasoning_content: item.reasoning_content,
        hasThinking: item.hasThinking,
        thinking_status: item.thinking_status,
        hasDeepSearch: item.hasDeepSearch,
        search_citations: item.search_citations
      });
    }

    refInput.value.isLoading = false;
    isStreamDone.value = true;
  }).catch(err => {
    // 处理错误 - 标记消息为失败状态
    const msgList = messageListRef.value.msgList;
    let item = msgList.find(item => item.id === id);
    if (item) {
      item.messageStatus = MESSAGE_STATUS.FAILED;
      item.showLoading = false;
      item.isRetrying = false;

      // 只保存原始消息内容用于重试，其他参数使用当前最新设置
      if (!item.originalContent) {
        item.originalContent = data.content || '';
      }
    }

    if (refInput.value) {
      refInput.value.isLoading = false;
    }
    isSend.value = false;
    isStreamDone.value = true;
  });
};

// 在发送消息时强制启用自动滚动
const onSendMsg = async (data) => {
  let id = new Date().getTime();
  msgId.value = id;

  // 从aiChatStore获取当前模型参数（mobile-app-navbar管理）
  const storeParams = aiChatStore.getAIChatParams() || {};
  
  // 合并参数，优先使用store中的model参数
  const finalParams = {
    content: data.content,
    model: storeParams.model || data.model || 'default-model',
    isThinking: storeParams.isThinking !== undefined ? storeParams.isThinking : (data.isThinking || false),
    enable_search: storeParams.enable_search !== undefined ? storeParams.enable_search : (data.enable_search || false)
  };
  
  console.log('发送消息 - 最终参数:', finalParams);

  // 创建用户消息对象
  const userMessage = onSendParseMsg({content: finalParams.content});
  // 创建AI助手消息对象（初始空消息，等待响应）
  const assistantMessage = onAIParseMsg({id}, true, false);

  // 如果是Think模式，为AI助手消息添加Think相关属性
  if (finalParams.isThinking) {
    assistantMessage.hasThinking = true;
    assistantMessage.reasoning_content = '';
    assistantMessage.thinking_status = 'start';
  }

  // 如果启用了DeepSearch，为AI助手消息添加DeepSearch相关属性
  if (finalParams.enable_search) {
    assistantMessage.hasDeepSearch = true;
    assistantMessage.isSearching = true;
    assistantMessage.search_citations = null;
    assistantMessage.deepSearchStreamData = null;
  }

  // 只保存原始消息内容用于重试，其他参数使用当前最新设置
  assistantMessage.originalContent = finalParams.content;

  // 将消息添加到UI显示列表
  messageListRef.value.addMessage(userMessage);
  messageListRef.value.addMessage(assistantMessage);

  isSend.value = true;
  refInput.value.isLoading = true;

  // 将用户消息和初始AI助手消息保存到 conversationStore
  if (sessionId.value) {
    // 添加用户消息到会话
    if (userMessage.id) {
      conversationStore.addMessageToConversation(sessionId.value, {
        id: userMessage.id,
        content: userMessage.content,
        role: userMessage.role,
        isMarkdown: userMessage.isMarkdown,
        timestamp: Date.now()
      });
    }

    // 添加初始AI助手消息到会话（空内容，等待流式更新）
    conversationStore.addMessageToConversation(sessionId.value, {
      id: assistantMessage.id,
      content: '',
      role: assistantMessage.role,
      isMarkdown: true,
      hasThinking: finalParams.isThinking || false,
      reasoning_content: '',
      thinking_status: 'start',
      hasDeepSearch: finalParams.enable_search || false,
      isSearching: finalParams.enable_search || false,
      search_citations: null,
      timestamp: Date.now()
    });
  }

  if(finalParams.isThinking){
    sendNormalMessage(finalParams, id);
  }else{
    sendStreamMessage(finalParams, id);
  }

  // 只有在正常发送消息时清除参数，从home页面跳转时在handleSessionCreationAndSend中处理
  if (sessionId.value) {
    aiChatStore.clearAIChatParams();
  }
};

const onSendStop = () => {
  isSend.value = false;
  refInput.value.isLoading = false;
  cancelStreamMessage();

  const msgList = messageListRef.value.msgList;
  let data = msgList.find(item => item.id === msgId.value);
  if (data) {
    data.showLoading = false;
    const cancelMessage = '\n\n ### Message Canceled';
    data.content = data.content + cancelMessage;
    data.typing = false;

    // 手动停止时更新 conversationStore 中的消息状态
    if (sessionId.value && data.id) {
      // 如果是DeepSearch，标记为已停止
      if (data.hasDeepSearch) {
        data.isSearching = false;
      }

      // 使用updateMessageInConversation方法更新现有消息
      conversationStore.updateMessageInConversation(sessionId.value, data.id, {
        content: data.content,
        role: MSG_ROLE_ASSISTANT,
        isMarkdown: true,
        hasDeepSearch: data.hasDeepSearch,
        isSearching: data.isSearching,
        search_citations: data.search_citations
      });
    }
    isStreamDone.value = false;
    // 使用组件引用执行组件方法（如果需要）
    const msgComponent = messageListRef.value.getItemRef(msgId.value);
    if (msgComponent) {
      // 调用组件的刷新方法
      msgComponent.onStopInterrupt();
    }
  }

  msgId.value = null;
};

/**
 * 立即显示消息到UI，提升用户体验
 * @param {object} chatParams - 聊天参数
 */
const showMessageImmediately = (chatParams) => {
  const id = new Date().getTime();
  msgId.value = id;

  // 创建用户消息对象
  const userMessage = onSendParseMsg({content: chatParams.content});
  // 创建AI助手消息对象（初始空消息，等待响应）
  const assistantMessage = onAIParseMsg({id}, true, false);

  // 如果是Think模式，为AI助手消息添加Think相关属性
  if (chatParams.isThinking) {
    assistantMessage.hasThinking = true;
    assistantMessage.reasoning_content = '';
    assistantMessage.thinking_status = 'start';
  }

  // 如果启用了DeepSearch，为AI助手消息添加DeepSearch相关属性
  if (chatParams.enable_search) {
    assistantMessage.hasDeepSearch = true;
    assistantMessage.isSearching = true;
    assistantMessage.search_citations = null;
    assistantMessage.deepSearchStreamData = null;
  }

  // 只保存原始消息内容用于重试，其他参数使用当前最新设置
  assistantMessage.originalContent = chatParams.content;

  // 立即将消息添加到UI显示列表
  if (messageListRef.value) {
    messageListRef.value.addMessage(userMessage);
    messageListRef.value.addMessage(assistantMessage);
  } else {
    // 如果组件还没挂载，等待下一个tick再尝试
    nextTick(() => {
      if (messageListRef.value) {
        messageListRef.value.addMessage(userMessage);
        messageListRef.value.addMessage(assistantMessage);
      }
    });
  }

  // 设置发送状态
  isSend.value = true;

  return { userMessage, assistantMessage, messageId: id };
};

/**
 * 处理session创建和消息发送
 * @param {object} chatParams - 聊天参数
 * @param {object} messageInfo - 消息信息
 */
const handleSessionCreationAndSend = async (chatParams, messageInfo) => {
  console.log('Mobile chatParams', chatParams);

  try {
    // 创建session
    const sessionRes = await ApiChat.createSession(chatParams.content, chatParams.model);

    // 更新session相关状态
    sessionId.value = sessionRes?.data?.id;
    conversationStore.appendConversations([sessionRes?.data]);
    conversationStore.setCurrentConversationId(sessionRes?.data?.id);

    // 更新路由
    router.replace({
      name: 'alien-chat',
      params: { sessionId: sessionRes?.data?.id }
    });

    // 将用户消息保存到 conversationStore
    if (sessionId.value && messageInfo.userMessage.id) {
      conversationStore.addMessageToConversation(sessionId.value, {
        id: messageInfo.userMessage.id,
        content: messageInfo.userMessage.content,
        role: messageInfo.userMessage.role,
        isMarkdown: messageInfo.userMessage.isMarkdown,
        timestamp: Date.now()
      });

      // 添加初始AI助手消息到会话（空内容，等待流式更新）
      conversationStore.addMessageToConversation(sessionId.value, {
        id: messageInfo.messageId,
        content: '',
        role: MSG_ROLE_ASSISTANT,
        isMarkdown: true,
        hasThinking: chatParams.isThinking || false,
        reasoning_content: '',
        thinking_status: 'start',
        hasDeepSearch: chatParams.enable_search || false,
        isSearching: chatParams.enable_search || false,
        search_citations: null,
        timestamp: Date.now()
      });
    }

    // 发送消息
    if (chatParams.isThinking) {
      sendNormalMessage(chatParams, messageInfo.messageId);
    } else {
      sendStreamMessage(chatParams, messageInfo.messageId);
    }

    // 清除chatParams
    aiChatStore.clearAIChatParams();

  } catch (error) {
    console.error('Failed to create session:', error);

    // 标记消息为失败状态
    if (messageListRef.value?.msgList) {
      const msgList = messageListRef.value.msgList;
      let item = msgList.find(item => item.id === messageInfo.messageId);
      if (item) {
        item.messageStatus = MESSAGE_STATUS.FAILED;
        item.showLoading = false;
        item.isRetrying = false;

        // 只保存原始消息内容用于重试，其他参数使用当前最新设置
        if (!item.originalContent) {
          item.originalContent = chatParams.content;
        }
      }
    }

    // 重置状态
    isSend.value = false;
    if (refInput.value) {
      refInput.value.isLoading = false;
    }
    msgId.value = null;
  }
};

// 周期函数区域
onBeforeMount(async () => {
 
});

onMounted(async () => {

  const chatParams = aiChatStore.getAIChatParams();
  const pathSegments = window.location.pathname.split('/');
  const pathSessionId = pathSegments[pathSegments.length - 1];

  if (pathSessionId && /^\d+$/.test(pathSessionId)) {
    sessionId.value = parseInt(pathSessionId);
    conversationStore.setCurrentConversationId(sessionId.value);
  }

  // 如果是从Home页面跳转过来且有消息内容，立即显示消息并异步处理
  if (!sessionId.value && pathSessionId && !/^\d+$/.test(pathSessionId) && chatParams?.content) {
    // 处理DeepSearch参数：确保enable_search字段存在
    const processedChatParams = {
      ...chatParams,
      enable_search: chatParams.enable_search || false
    };

    console.log('Processing mobile chat params from Home:', processedChatParams);

    // 立即显示消息到UI
    const messageInfo = showMessageImmediately(processedChatParams);

    // 等待组件挂载完成后异步处理session创建和消息发送
    await nextTick();
    if (refInput.value) {
      refInput.value.isLoading = true;
    }
    handleSessionCreationAndSend(processedChatParams, messageInfo);
  }

  window.addEventListener('resize', handleResize);
  getBottomHeight();
});

onUnmounted(() => {
  cleanupEventListeners();
});

onBeforeUnmount(() => {
  if (streamConnection.value) {
    streamConnection.value.close();
    streamConnection.value = null;
  }
  conversationStore.setCurrentConversationId(null);
});

// 监听路由参数变化
watch( async () => route.params, async (newSessionId) => {
  let paramsSessionId = route.params.sessionId;
  // 检查新的sessionId是否存在且与当前sessionId不同
  if (paramsSessionId && parseInt(paramsSessionId) !== sessionId.value) {
    sessionId.value = parseInt(paramsSessionId);
    conversationStore.setCurrentConversationId(sessionId.value);
    nextTick(() => {
     setTimeout(() => {
      if(messageListRef.value){
        messageListRef.value.getMsgList(true, false);
      }
     }, 100);
      // 移动端可能不需要搜索侧边栏，暂时保留但可以考虑移除
      window.dispatchEvent(new CustomEvent('toggleSearchSidebar', {
        detail: {
          citations: [],
          show: false
        }
      }));
    });
  }
}, { immediate: true, deep: true });
</script>

